    /**
     * Tests getting all Promotions.
     *
     * @return    Collection
     */
    public List<Promotion> testGetAll() throws Throwable {
    LOGGER.info( "PromotionTest:testGetAll() - Retrieving Collection of Promotions:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Promotion : " );
    List<Promotion> collection  = null;

    try {
        // call the static get method on the PromotionService
        collection = service.getAllPromotion();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Promotion currEntity  = null;
            Iterator<Promotion> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPromotionId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

